// Using i32 as a reasonable stand-in for the problem's "mathematical integers".
// If you need a different integer type, change i32 to i64/isize/etc.
pub fn get_triple(a: &[i32]) -> usize {
    let n = a.len();
    if n < 3 {
        return n;
    }

    for i in 0..=n - 3 {
        if a[i] == a[i + 1] && a[i] == a[i + 2] {
            return i;
        }
    }

    n
}

